#include <stdio.h>

#define MAXF 8

/* 简单 Clock：只看访问位 */
int simple_clock(const int *r, int n, int m, int *writebacks) {
    int q[MAXF], a[MAXF], dirty[MAXF], f = 0, ptr = 0, faults = 0, wb = 0;
    for (int i = 0; i < n; i++) {
        int hit = -1;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { hit = j; break; }
        if (hit >= 0) { a[hit] = 1; dirty[hit] = 1; continue; }   /* 访问即置脏（最坏情形） */
        faults++;
        if (f < m) { q[f] = r[i]; a[f] = 1; dirty[f] = 1; f++; continue; }
        while (a[ptr] == 1) { a[ptr] = 0; ptr = (ptr + 1) % m; }
        if (dirty[ptr]) wb++;
        q[ptr] = r[i]; a[ptr] = 1; dirty[ptr] = 1; ptr = (ptr + 1) % m;
    }
    *writebacks = wb;
    return faults;
}

/* 改进型 Clock：访问位 A + 修改位 M，四步扫描 */
int improved_clock(const int *r, int n, int m, int *writebacks) {
    int q[MAXF], A[MAXF], M[MAXF], f = 0, ptr = 0, faults = 0, wb = 0;
    for (int i = 0; i < n; i++) {
        int hit = -1;
        for (int j = 0; j < f; j++) if (q[j] == r[i]) { hit = j; break; }
        if (hit >= 0) { A[hit] = 1; M[hit] = 1; continue; }
        faults++;
        if (f < m) { q[f] = r[i]; A[f] = 1; M[f] = 1; f++; continue; }
        /* 第 1 轮：找 (A=0, M=0) */
        int victim = -1;
        for (int k = 0; k < 2 * m && victim < 0; k++) {
            int j = (ptr + k) % m;
            if (A[j] == 0 && M[j] == 0) { victim = j; break; }
            if (A[j] == 1) A[j] = 0;
        }
        /* 第 2 轮：找 (A=0, M=1) */
        for (int k = 0; k < 2 * m && victim < 0; k++) {
            int j = (ptr + k) % m;
            if (A[j] == 0 && M[j] == 1) { victim = j; break; }
            if (A[j] == 1) A[j] = 0;
        }
        if (victim < 0) victim = ptr;
        if (M[victim]) wb++;
        q[victim] = r[i]; A[victim] = 1; M[victim] = 0;   /* 新页先算干净，被写才置脏 */
        ptr = (victim + 1) % m;
    }
    *writebacks = wb;
    return faults;
}

int main(void) {
    int ref[] = {7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1};
    int n = 20, m = 3;
    int wb1 = 0, wb2 = 0;
    int f1 = simple_clock(ref, n, m, &wb1);
    int f2 = improved_clock(ref, n, m, &wb2);
    printf("reference string len=%d, frames=%d\n", n, m);
    printf("simple   clock: faults=%d  writebacks=%d\n", f1, wb1);
    printf("improved clock: faults=%d  writebacks=%d\n", f2, wb2);
    printf("improved clock prefers (A=0,M=0) clean pages -> fewer or equal writebacks\n");
    printf("fault diff = %d, writeback diff = %d\n", f1 - f2, wb1 - wb2);
    return 0;
}
